'use strict';
// Investigation tests, NOT a declaration that the live blocker is fixed.
// Only timestamps/session come from the field report. Full frames and callback
// metadata were not captured there; frames below are generated by the real 620.
const assert=require('node:assert/strict');
const fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process');
const {create,root}=require('./harness');
const times=[1790323099053,1790323104779,1790323109642,1790323114554,1790323119507,1790323124529];
const old='14354bcf1e0033c51f02f0b242bea8aa7fa29e4e';
let count=0;
function test(name,fn){fn();count++;console.log('PASS '+name);}
function transform(name,source){
    if(name!=='HHM3Wire')return source;
    // Test-only closure inspection; never included in deployable runtime bytes.
    const marker='        accept: function (payload, retained, now) {';
    assert.equal(source.split(marker).length,2);
    return source.replace(marker,'        debugState: function () { return {first:first, firstSent:firstSent, session:session, seq:seq, sent:sent, received:received, barrier:barrier, lastNow:lastNow, ready:ready, reason:reason}; },\n'+marker);
}
function startup(order){
    const seed=create(),values={boiler:{},gazebo:{}},retained={boiler:{},gazebo:{}};
    for(const board of ['boiler','gazebo']){
        const data=board==='boiler'?seed.temperatures:seed.gazeboTemperatures;
        for(const [p,v]of Object.entries({...data,...seed.health[board]})){
            values[board][p]=v;values[board][p+'#error']='';retained[board][seed.topic(p)]=v;
        }
    }
    for(const z of seed.Z)values.boiler['NL_simple_thermostat_'+z.id+'/target_state']=true;
    return create({epoch:times[0],values,retained,wb2465Replay:true,
        moduleTransform:transform,startOrder:order,
        stores:{hhm3_operation:{inService:true},hhm3_house_sender:{session_id:28}}});
}
function runWindow(h){
    const trace=[];
    for(let i=0;i<times.length;i++){
        h.time(times[i]);if(i)h.tick('620');h.tick('500');h.tick('600');
        trace.push(JSON.parse(JSON.stringify(h.contexts['500'].house.debugState())));
    }
    return trace;
}
const orders=[['500','620','624','600'],['620','500','624','600']];
if(process.argv.includes('--verify-baseline'))test('investigated production bytes are still exactly the failed live runtime, not a speculative fix',()=>{
    const prefix='objects/05_31_Ivolga_13/HHM3_FSE/';
    for(const file of ['modules/HHM3Wire.js','modules/HHM3Runtime.js','boiler/wb-rules/500_HHM3_FSE.js','boiler/wb-rules/620_thermostats.js']){
        const pinned=cp.execFileSync('git',['show',old+':'+prefix+file],{cwd:root,encoding:'utf8'});
        assert.equal(fs.readFileSync(path.join(root,file),'utf8').replace(/\r\n/g,'\n'),pinned);
    }
});
test('exact live times qualify house receiver with valid 620 frames and boolean false callbacks in both orders',()=>{
    for(const order of orders){
        const h=startup(order),trace=runWindow(h);
        const frames=h.messages.filter(m=>m.topic===h.C.houseTopic).map(m=>JSON.parse(m.payload));
        assert.deepEqual(frames.map(f=>f.sent_ms),times);
        assert.deepEqual(frames.map(f=>f.seq),[1,2,3,4,5,6]);
        assert.ok(frames.every(f=>f.session_id===29&&h.load('HHM3Runtime').houseValid(f)));
        const callbacks=h.callbacks.filter(c=>c.owner==='500'&&c.topic===h.C.houseTopic);
        assert.ok(callbacks.every(c=>c.retained===false&&c.qos===0));
        assert.equal(trace.find(s=>s.ready).seq,order[0]==='500'?2:4);
        assert.match(h.values.boiler['HHM3_FSE/runtime_status'],/дом NORMAL/);
        assert.equal(trace.at(-1).barrier,times[0]);
        assert.equal(trace.at(-1).seq,6);
        console.log('TRACE '+order.join('->')+' '+JSON.stringify(trace));
    }
});
test('WB 2.46.5 shared subscription replays only to joining trackers, with retained=true',()=>{
    const h=startup(orders[0]),p=h.C.circuits['502'].supply;
    const initial=h.callbacks.filter(c=>c.topic===h.topic(p));
    assert.ok(initial.some(c=>c.owner==='500'&&c.retained===true));
    assert.ok(initial.some(c=>c.owner==='600'&&c.retained===true));
    const before=h.callbacks.length;
    h.deliver('boiler',h.topic(p),26,false);
    const live=h.callbacks.slice(before).filter(c=>c.topic===h.topic(p));
    assert.ok(live.some(c=>c.owner==='500'));assert.ok(live.some(c=>c.owner==='600'));
    assert.ok(live.every(c=>c.retained===false));
});
test('BLOCKER reproduced: healthy unchanged controls and unavailable retained-only controls are indistinguishable inside 30 s',()=>{
    for(const order of orders){
        // Healthy: next unchanged publication is at +60 s (outside acceptance).
        // Unavailable: producer unavailable, retained state still in broker.
        // Both expose the SAME public observations before that next publication.
        const healthy=startup(order),unavailable=startup(order);
        assert.deepEqual(runWindow(healthy),runWindow(unavailable));
        assert.deepEqual(healthy.callbacks,unavailable.callbacks);
        assert.deepEqual(healthy.values,unavailable.values);
        for(const h of [healthy,unavailable]){
            for(const z of h.Z.filter(z=>h.C.m1w2Health[z.sensor]))
                assert.equal(h.values.boiler['NL_simple_thermostat_'+z.id+'/valid'],false);
            for(const pair of h.contexts['600'].HD_PAIRS)
                assert.equal(h.values.boiler['heat_diagnostics/'+pair.id],'нет данных');
            assert.equal(h.values.boiler['HHM3_FSE/sensor_health_contract'],'m1w2-health-v1');
            assert.equal(h.contexts['500'].house.read(h.now()).fresh,true);
            h.time(times[0]+29999);h.tick('620');h.tick('500');h.tick('600');
            assert.equal(h.values.boiler['NL_simple_thermostat_'+h.Z.find(z=>z.kind==='floor').id+'/valid'],false);
        }
    }
});
test('a numeric update alone cannot prove retained OK; actual live pair qualifies and genuine faults invalidate',()=>{
    const h=startup(orders[0]),z=h.Z.find(z=>z.kind==='floor'),ok=h.C.m1w2Health[z.sensor];
    h.time(times[1]);h.deliver('boiler',h.topic(z.sensor),20,false);h.tick('620');
    assert.equal(h.values.boiler['NL_simple_thermostat_'+z.id+'/valid'],false);
    h.deliver('boiler',h.topic(ok),1,false);h.tick('620');
    assert.equal(h.values.boiler['NL_simple_thermostat_'+z.id+'/valid'],true);
    h.deliver('boiler',h.topic(ok),0,false);h.tick('620');
    assert.equal(h.values.boiler['NL_simple_thermostat_'+z.id+'/valid'],false);
    h.deliver('boiler',h.topic(ok),1,false);h.tick('620');
    assert.equal(h.values.boiler['NL_simple_thermostat_'+z.id+'/valid'],true);
    h.deliver('boiler',h.topic(z.sensor)+'/meta/error','r',false);h.tick('620');
    assert.equal(h.values.boiler['NL_simple_thermostat_'+z.id+'/valid'],false);
});
console.log('RESULT: '+count+' investigation groups PASS; release acceptance remains BLOCKED, not fixed.');
if(process.argv.includes('--acceptance')){
    const h=startup(orders[0]);runWindow(h);
    // Deliberately red acceptance probe; not inverted or registered as a green
    // deployment check. Same assertion must eventually pass on a proven fix.
    for(const z of h.Z.filter(z=>h.C.m1w2Health[z.sensor]))
        assert.equal(h.values.boiler['NL_simple_thermostat_'+z.id+'/valid'],true,
            'BLOCKED: healthy retained/unchanged M1W2 must qualify before 30 s: '+z.id);
}
